<?php function shop_e($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}$currencyNames=['credits'=>'Crédits','duckets'=>'Duckets','diamonds'=>'Diamants'];$rewardNames=['credits'=>'crédits','duckets'=>'duckets','diamonds'=>'diamants','vip'=>'VIP'];?>
<div class="content"><div class="container">
<section class="shop-head"><img src="<?php echo URL; ?>/avatar.php?figure=<?php echo rawurlencode($UData['look']); ?>&size=l&direction=3" alt=""><div><span>BOUTIQUE OFFICIELLE</span><h1>Boutique ParadiseRP</h1><p>Avantages et monnaies attribués directement à ton compte.</p></div><div class="shop-balances"><div><b><?php echo number_format((int)$UData['credits'],0,',',' '); ?></b><small>Crédits</small></div><div><b><?php echo number_format((int)$UData['activity_points'],0,',',' '); ?></b><small>Duckets</small></div><div><b><?php echo number_format((int)$UData['vip_points'],0,',',' '); ?></b><small>Diamants</small></div></div></section>
<?php if($ShopNotice):?><div class="shop-message ok"><i class="fas fa-check-circle"></i><?php echo shop_e($ShopNotice); ?></div><?php endif?><?php if($ShopError):?><div class="shop-message err"><i class="fas fa-exclamation-circle"></i><?php echo shop_e($ShopError); ?></div><?php endif?>
<div class="shop-layout"><aside class="shop-categories"><a class="<?php echo !$category?'active':''; ?>" href="<?php echo URL; ?>/store">Tous les produits</a><?php while($c=mysqli_fetch_assoc($ShopCategories)):?><a class="<?php echo $category==(int)$c['id']?'active':''; ?>" href="?category=<?php echo (int)$c['id']; ?>"><span><?php echo shop_e($c['name']); ?></span><small><?php echo (int)$c['products']; ?></small></a><?php endwhile?><a href="#history"><i class="fas fa-history"></i> Mes achats</a></aside><main class="shop-main"><div class="shop-section-title"><div><span>CATALOGUE</span><h2>Produits disponibles</h2></div></div><div class="shop-products"><?php if(mysqli_num_rows($ShopProducts)):while($p=mysqli_fetch_assoc($ShopProducts)):$image=$p['image_url']?:DY.'/img/store/vip.png';?><article class="shop-product <?php echo $p['featured']?'featured':''; ?>"><div class="shop-product-image" style="background-image:url('<?php echo shop_e($image); ?>')"><?php if($p['badge']):?><span><?php echo shop_e($p['badge']); ?></span><?php endif?></div><div class="shop-product-body"><small><?php echo shop_e($p['category_name']); ?></small><h3><?php echo shop_e($p['name']); ?></h3><p><?php echo shop_e($p['description']); ?></p><div class="shop-reward">Reçoit : <b><?php echo (int)$p['reward_amount'].' '.shop_e($rewardNames[$p['reward_type']]??$p['reward_type']); ?><?php echo $p['reward_type']==='vip'?' · '.(int)$p['duration_days'].' jours':''; ?></b></div><?php if($p['stock']!==null):?><small class="shop-stock"><?php echo max(0,(int)$p['stock']); ?> restant(s)</small><?php endif?><div class="shop-buy"><strong><?php echo number_format((int)$p['current_price'],0,',',' '); ?> <small><?php echo shop_e($currencyNames[$p['currency']]); ?></small></strong><form method="post"><input type="hidden" name="csrf" value="<?php echo shop_e($_SESSION['shop_csrf']); ?>"><input type="hidden" name="request_token" value="<?php echo shop_e($_SESSION['shop_request_token']); ?>"><input type="hidden" name="action" value="buy"><input type="hidden" name="product_id" value="<?php echo (int)$p['id']; ?>"><button data-product="<?php echo shop_e($p['name']); ?>" data-price="<?php echo (int)$p['current_price'].' '.shop_e($currencyNames[$p['currency']]); ?>">Acheter</button></form></div></div></article><?php endwhile;else:?><div class="shop-empty">Aucun produit disponible dans cette catégorie.</div><?php endif?></div>
<section id="history" class="shop-history content-box"><div class="title">Historique de mes achats</div><div class="shop-history-scroll"><table><thead><tr><th>Produit</th><th>Prix</th><th>Date</th><th>Statut</th></tr></thead><tbody><?php if(mysqli_num_rows($ShopHistory)):while($o=mysqli_fetch_assoc($ShopHistory)):?><tr><td><?php echo shop_e($o['product_name']); ?></td><td><?php echo number_format((int)$o['price'],0,',',' ').' '.shop_e($currencyNames[$o['currency']]??$o['currency']); ?></td><td><?php echo date('d/m/Y H:i',(int)$o['created_at']); ?></td><td><span class="shop-order-status"><?php echo $o['status']==='completed'?'Effectué':'Échec'; ?></span></td></tr><?php endwhile;else:?><tr><td colspan="4">Aucun achat pour le moment.</td></tr><?php endif?></tbody></table></div></section></main></div></div></div>
<script>document.querySelectorAll('.shop-buy form').forEach(function(form){form.addEventListener('submit',function(e){var b=form.querySelector('button');if(!confirm('Confirmer l’achat de '+b.dataset.product+' pour '+b.dataset.price+' ?'))e.preventDefault()})});</script>
